/// <summary>
/// MPJ_22903_SalesOrderGuide
/// Handles execution of sales order guides (applying checks and updates to orders
/// based on applicable guide).
/// </summary>
class METSalesOrderGuideExecution
{
    // Params
    SalesId                     salesID;

    // State
    METCustParameters           metCustParams;
    SalesTable                  salesTable;
    METCustTable                metCustTable; 
    CustTable                   custTable;

}

Method.Source:
    /// <summary>
    /// run
    /// </summary>
    public void run()
    {
        metCustParams = METCustParameters::Find();
        
        setPrefix("@MET:SalesOrderGuideProcessInfoLogPrefix");

        salesTable = SalesTable::find(salesId);
        if(!salesTable)
        {
            throw error(strFmt("@MET:SalesOrderNotFound", salesId));
        }

        SalesLine       salesLine;
        METSalesLine    metSalesLine;

        metCustTable    = METCustTable::find(salesTable.CustAccount);        
        custTable       = salesTable.custTable_CustAccount();

        ttsbegin;

        while select forupdate salesLine
            where   salesLine.SalesId       == salesTable.SalesId
        join forupdate metSalesLine
            where   metSalesLine.SalesLine  == salesLine.RecId
        {
            if(!this.isLineOrderable(salesLine))
            {
                salesLine.RemainInventPhysical  = 0;
                salesLine.RemainInventFinancial = 0;
                salesLine.RemainSalesPhysical   = 0;
                salesLine.RemainSalesFinancial  = 0;

                if(metCustParams.OrderGuideNotInRangeReasonId)
                {
                    metSalesLine.ReasonID = metCustParams.OrderGuideNotInRangeReasonId;
                    metSalesLine.update();
                }
                salesLine.update();
                warning(strFmt("@MET:SalesOrderGuideLineCancelledMessage", salesLine.ItemId));
            }
        }
        ttscommit;        
    }

    /// <summary>
    /// Check if sales order line is orderable based on matching order guide entries.
    /// </summary>
    /// <param name = "_salesLine">_salesLine</param>
    /// <returns>True if the line is orderable. False if not (requires cancellation)</returns>
    protected boolean isLineOrderable(SalesLine _salesLine)
    {
        boolean inclusionFound, exclusionFound;

        METSalesOrderGuideItem guideItem;

        // TODO confirm - If a guide line is defined only at item level, and 
        // an order line specifies a variant, should that guide line be considered,
        // or do they have to match excactly?

        select firstonly RecId from guideItem
            where   guideItem.ItemId            == _salesLine.ItemId
            &&      guideItem.RetailVariantId   == _salesLine.RetailVariantId;

        if(!guideItem)
        {
            // No entry at all for specified item so it's orderable.
            return true;
        }

        while select guideItem
            where   guideItem.ItemId            == _salesLine.ItemId
            &&      guideItem.RetailVariantId   == _salesLine.RetailVariantId
            && (
                       (guideItem.ReferenceType == METSalesOrderGuideReferenceType::Customer                    && guideItem.Reference == salesTable.CustAccount)
                    || (guideItem.ReferenceType == METSalesOrderGuideReferenceType::CustomerOperationsGroup     && guideItem.Reference == metCustTable.CustOperGroupId)
                    || (guideItem.ReferenceType == METSalesOrderGuideReferenceType::Site                        && guideItem.Reference == custTable.InventSiteId)
                    || (guideItem.ReferenceType == METSalesOrderGuideReferenceType::State                       && guideItem.Reference == _salesLine.deliveryAddress().State)
            )
        {
            switch(guideItem.LineType)
            {
                case METSalesOrderGuideInclusion::Include:
                    inclusionFound = true;
                    break;
                case METSalesOrderGuideInclusion::Exclude:
                    exclusionFound = true;
                    break;
            }
        }
        if(exclusionFound)
        {
            // Specific exclusion found
            return false;
        }
        else
        {
            if(inclusionFound)
            {
                // Specific inclusion found
                return true;
            }
            else
            {
                // No specific exclusion, or inclusion, but item is referenced
                // at least once in the order guide set up.
                return false;
            }
        }
    }

/// <summary>
/// Get/set sales ID
/// </summary>
/// <param name = "_salesID">_salesID</param>
/// <returns>salesID</returns>
public SalesID parmSalesID(SalesId _salesID = salesID)
{
    salesID = _salesID;
    return salesID;
}

/// <summary>
/// Apply order guide checks to specified order.
/// </summary>
/// <param name = "_salesID">Sales order</param>
static void applyChecksToOrder(SalesId _salesID)
{
    METSalesOrderGuideExecution exec = new METSalesOrderGuideExecution();
    exec.parmSalesID(_salesID);
    exec.run();
}

    /// <summary>
    /// main
    /// </summary>
    /// <param name = "_args">_args</param>
    static public void main(Args _args)
    {
        SalesTable salesTable = _args.record();
        if(!salesTable)
        {
            throw error(error::missingRecord(funcName()));
        }
        if(Box::yesNo(strFmt("@MET:SalesOrderGuideApplyPrompt", salesTable.SalesId), DialogButton::No) != DialogButton::Yes)
        {
            throw Exception::Break;
        }

        METSalesOrderGuideExecution::applyChecksToOrder(salesTable.SalesId);

        if(FormDataUtil::getFormDataSource(salesTable))
        {
            FormDataUtil::getFormDataSource(salesTable).research(true);
        }
    }
